from typing import List, Dict, Any, Optional
from pydantic import BaseModel, Field
from app.schemas.evidence import (
    GraphRecord,
    ClinicalNote,
    AdmissionRecord,
    ClaimVerification
)


class InvestigationPlan(BaseModel):
    """Structured execution plan generated by the Question Understanding & Planning Agent."""
    intent: str = Field(..., description="Summary of the clinical question's objective")
    identified_entities: Dict[str, List[str]] = Field(
        default_factory=lambda: {"medications": [], "conditions": [], "lab_tests": [], "admissions": []},
        description="Categorized clinical entities extracted from the question"
    )
    temporal_requirements: List[str] = Field(
        default_factory=list,
        description="Temporal cues such as latest, previous, between, before, after"
    )
    required_data_sources: List[str] = Field(
        default_factory=lambda: ["graph", "vector", "admissions"],
        description="Target backends needed to fulfill the plan"
    )
    planned_steps: List[str] = Field(
        default_factory=list,
        description="Step-by-step clinical investigation methodology"
    )
    graph_queries: List[str] = Field(
        default_factory=list,
        description="Targeted queries formulated for the structured graph API"
    )
    vector_queries: List[str] = Field(
        default_factory=list,
        description="Targeted queries formulated for the semantic vector search API"
    )


class FinalAnswer(BaseModel):
    """Final evidence-grounded clinical investigation report for the frontend/API."""
    patient_id: str = Field(..., description="Target patient ID")
    question: str = Field(..., description="User's original question")
    direct_answer: str = Field(..., description="Direct, concise clinical answer to the question")
    key_findings: List[str] = Field(default_factory=list, description="Primary clinical takeaways")
    chronological_changes: List[Dict[str, Any]] = Field(
        default_factory=list,
        description="Timeline breakdown of admissions, lab changes, and medication shifts"
    )
    supporting_evidence: List[Dict[str, Any]] = Field(
        default_factory=list,
        description="Evidence cards detailing finding, record ID, timestamp, and status"
    )
    source_record_ids: List[str] = Field(
        default_factory=list,
        description="All distinct record IDs cited in this response"
    )
    timestamps: List[str] = Field(
        default_factory=list,
        description="All relevant timestamps referenced"
    )
    contradictions_or_missing_info: List[str] = Field(
        default_factory=list,
        description="Explicit documentation of conflicting facts or absent records"
    )
    limitations: List[str] = Field(
        default_factory=list,
        description="Distinguishes documented clinical facts from unknown/uncaused information"
    )
    claims_verification: List[ClaimVerification] = Field(
        default_factory=list,
        description="Audit trail of individual claim verification outcomes"
    )
    verification_summary: Dict[str, int] = Field(
        default_factory=dict,
        description="Aggregate counts for SUPPORTED, CONTRADICTED, INSUFFICIENT, NOT_FOUND"
    )
    all_claims_verified: bool = Field(..., description="True if no claims are contradicted or unverified")


# API response schemas matching the contract with the main application
class GraphSearchResponse(BaseModel):
    patient_id: str
    records: List[GraphRecord] = Field(default_factory=list)
    total: int = 0


class VectorSearchResponse(BaseModel):
    patient_id: str
    notes: List[ClinicalNote] = Field(default_factory=list)
    total: int = 0


class AdmissionHistoryResponse(BaseModel):
    patient_id: str
    admissions: List[AdmissionRecord] = Field(default_factory=list)
    total: int = 0
